     2	import * as path from "node:path";
     3	
     4	type AtomicJsonFs = Pick<typeof fs, "mkdirSync" | "writeFileSync" | "renameSync" | "rmSync">;
     5	
     6	type AtomicJsonWriterOptions = {
     7		fs?: AtomicJsonFs;
     8		now?: () => number;
     9		pid?: number;
    10		random?: () => number;
    11		mode?: number;
    12		retryRenameErrors?: boolean;
    13		retryDelaysMs?: readonly number[];
    14		wait?: (delayMs: number) => void;
    15	};
    16	
    17	const DEFAULT_RENAME_RETRY_DELAYS_MS = [10, 25, 50, 100, 200, 500, 1000, 2000, 4000] as const;
    18	const RETRYABLE_RENAME_ERROR_CODES = new Set(["EACCES", "EBUSY", "EPERM"]);
    19	const WAIT_BUFFER = typeof SharedArrayBuffer !== "undefined" ? new SharedArrayBuffer(4) : undefined;
    20	const WAIT_VIEW = WAIT_BUFFER ? new Int32Array(WAIT_BUFFER) : undefined;
    21	
    22	function waitSync(delayMs: number): void {
    23		if (delayMs <= 0) return;
    24		if (WAIT_VIEW) {
    25			try {
    26				// writeAtomicJson is synchronous because callers often update status from sync callbacks.
    27				// Atomics.wait gives Windows rename locks time to clear without burning CPU.
    28				Atomics.wait(WAIT_VIEW, 0, 0, delayMs);
    29				return;
    30			} catch {
    31				// Fall through to the portable busy wait below.
    32			}
    33		}
    34		const end = Date.now() + delayMs;
    35		while (Date.now() < end) {
    36			// Portable fallback for runtimes where Atomics.wait is unavailable.
    37		}
    38	}
    39	
    40	function isRetryableRenameError(error: unknown): boolean {
    41		const code = (error as NodeJS.ErrnoException | undefined)?.code;
    42		return typeof code === "string" && RETRYABLE_RENAME_ERROR_CODES.has(code);
    43	}
    44	
    45	function renameWithRetry(
    46		fsImpl: AtomicJsonFs,
    47		sourcePath: string,
    48		targetPath: string,
    49		retryDelaysMs: readonly number[],
    50		wait: (delayMs: number) => void,
    51	): void {
    52		for (let attempt = 0; ; attempt++) {
    53			try {
    54				fsImpl.renameSync(sourcePath, targetPath);
    55				return;
    56			} catch (error) {
    57				const delayMs = retryDelaysMs[attempt];
    58				if (delayMs === undefined || !isRetryableRenameError(error)) throw error;
    59				wait(delayMs);
    60			}
    61		}
    62	}
    63	
    64	export function createAtomicJsonWriter(options: AtomicJsonWriterOptions = {}): (filePath: string, payload: object) => void {
    65		const fsImpl = options.fs ?? fs;
    66		const now = options.now ?? Date.now;
    67		const pid = options.pid ?? process.pid;
    68		const random = options.random ?? Math.random;
    69		const mode = options.mode;
    70		const retryRenameErrors = options.retryRenameErrors ?? process.platform === "win32";
    71		const retryDelaysMs = retryRenameErrors ? options.retryDelaysMs ?? DEFAULT_RENAME_RETRY_DELAYS_MS : [];
    72		const wait = options.wait ?? waitSync;
    73		return (filePath: string, payload: object): void => {
    74			fsImpl.mkdirSync(path.dirname(filePath), { recursive: true });
    75			const tempPath = path.join(
    76				path.dirname(filePath),
    77				`.${path.basename(filePath)}.${pid}.${now()}.${random().toString(36).slice(2)}.tmp`,
    78			);
    79			try {
    80				fsImpl.writeFileSync(tempPath, JSON.stringify(payload, null, 2), mode === undefined ? "utf-8" : { encoding: "utf-8", mode });
    81				renameWithRetry(fsImpl, tempPath, filePath, retryDelaysMs, wait);
    82			} finally {
    83				fsImpl.rmSync(tempPath, { force: true });
    84			}
    85		};
    86	}
    87	
    88	export const writeAtomicJson = createAtomicJsonWriter();
    89	export const writePrivateAtomicJson = createAtomicJsonWriter({ mode: 0o600 });

