    80			fs.appendFileSync(filePath, `${JSON.stringify(payload)}\n`, "utf-8");
    81		} catch {
    82			// Repair status/result writes are the important path. A broken or full
    83			// diagnostic event log must not make stale-run reconciliation fail.
    84		}
    85	}
    86	
    87	function readStatusFile(asyncDir: string): AsyncStatus | null {
    88		const statusPath = path.join(asyncDir, "status.json");
    89		let content: string;
    90		try {
    91			content = fs.readFileSync(statusPath, "utf-8");
    92		} catch (error) {
    93			if (isNotFoundError(error)) return null;
    94			throw new Error(`Failed to read async status file '${statusPath}': ${getErrorMessage(error)}`, {
    95				cause: error instanceof Error ? error : undefined,
    96			});
    97		}
    98		try {
    99			return JSON.parse(content) as AsyncStatus;
   100		} catch (error) {
   101			throw new Error(`Failed to parse async status file '${statusPath}': ${getErrorMessage(error)}`, {
   102				cause: error instanceof Error ? error : undefined,
   103			});
   104		}
   105	}
   106	
   107	interface ResultChildOutcome {
   108		agent?: string;
   109		success?: boolean;
   110		error?: string;
   111		sessionFile?: string;
   112		model?: string;
   113		thinking?: string;
   114		attemptedModels?: string[];
   115		modelAttempts?: NonNullable<AsyncStatus["steps"]>[number]["modelAttempts"];
   116	}
   117	
   118	interface ResultRepairData {
   119		state: "complete" | "failed" | "paused" | "stopped";
   120		results?: ResultChildOutcome[];
   121	}
   122	
   123	function readResultRepairData(resultPath: string): ResultRepairData | undefined {
   124		try {
   125			const data = JSON.parse(fs.readFileSync(resultPath, "utf-8")) as { success?: boolean; state?: string; exitCode?: number; results?: unknown };
   126			const state = data.success ? "complete" : data.state === "stopped" ? "stopped" : data.state === "paused" || data.exitCode === 0 ? "paused" : "failed";
   127			const results = Array.isArray(data.results)
   128				? data.results.map((entry, index) => {
   129					if (!entry || typeof entry !== "object" || Array.isArray(entry)) return {};
   130					const child = entry as ResultChildOutcome;
   131					if (child.model !== undefined && typeof child.model !== "string") throw new Error(`Invalid async result file '${resultPath}': results[${index}].model must be a string.`);
   132					if (child.thinking !== undefined && typeof child.thinking !== "string") throw new Error(`Invalid async result file '${resultPath}': results[${index}].thinking must be a string.`);
   133					return child;
   134				})
   135				: undefined;
   136			return { state, ...(results ? { results } : {}) };
   137		} catch (error) {
   138			if (isNotFoundError(error)) return undefined;
   139			throw new Error(`Failed to read async result file '${resultPath}': ${getErrorMessage(error)}`, {
   140				cause: error instanceof Error ? error : undefined,
   141			});
   142		}
   143	}
   144	
   145	function childState(overallState: ResultRepairData["state"], child: ResultChildOutcome | undefined): "complete" | "failed" | "paused" | "stopped" {
   146		if (child?.success === true) return "complete";
   147		if (child?.success === false) return "failed";
   148		return overallState;
   149	}
   150	
   151	function terminalStatusFromResult(status: AsyncStatus, resultPath: string, now: number): AsyncStatus | undefined {
   152		const repair = readResultRepairData(resultPath);
   153		if (!repair) return undefined;
   154		const steps = (status.steps ?? []).map((step, index) => {
   155			if (step.status !== "running" && step.status !== "pending") return step;
   156			const child = repair.results?.[index];
   157			const state = childState(repair.state, child);
   158			const model = child?.model ?? step.model;
   159			const thinking = resolveEffectiveThinking(model, child?.thinking ?? step.thinking);
   160			return {
   161				...step,
   162				status: state === "complete" ? "complete" as const : state,
   163				endedAt: step.endedAt ?? now,
   164				durationMs: step.startedAt !== undefined && step.durationMs === undefined ? Math.max(0, now - step.startedAt) : step.durationMs,
   165				exitCode: step.exitCode ?? (state === "complete" || state === "paused" ? 0 : 1),
   166				error: state === "failed" || state === "stopped" ? step.error ?? child?.error : step.error,
   167				stopped: state === "stopped" ? true : step.stopped,
   168				sessionFile: step.sessionFile ?? child?.sessionFile,
   169				model,
   170				thinking,
   171				attemptedModels: child?.attemptedModels ?? step.attemptedModels,
   172				modelAttempts: child?.modelAttempts ?? step.modelAttempts,
   173			};
   174		});
   175		return {
   176			...status,
   177			state: repair.state,
   178			...(repair.state === "stopped" ? { stopped: true } : {}),
   179			activityState: undefined,
   180			lastUpdate: now,
   181			endedAt: status.endedAt ?? now,
   182			steps,
   183		};
   184	}
   185	
   186	function buildStartedStatus(asyncDir: string, startedRun: StartedRunMetadata, now: number): AsyncStatus {
   187		const startedAt = startedRun.startedAt ?? now;
   188		const agents = startedRun.agents?.length ? startedRun.agents : ["subagent"];
   189		const chainStepCount = startedRun.chainStepCount;
   190		const parallelGroups = chainStepCount !== undefined
   191			? normalizeParallelGroups(startedRun.parallelGroups, agents.length, chainStepCount)
   192			: [];
   193		return {
   194			runId: startedRun.runId || path.basename(asyncDir),
   195			...(startedRun.sessionId ? { sessionId: startedRun.sessionId } : {}),
   196			mode: startedRun.mode ?? "single",
   197			state: "running",
   198			pid: startedRun.pid,
   199			startedAt,
   200			lastUpdate: now,
   201			currentStep: 0,
   202			...(chainStepCount !== undefined ? { chainStepCount } : {}),
   203			...(parallelGroups.length ? { parallelGroups } : {}),
   204			steps: agents.map((agent) => ({
   205				agent,
   206				status: "running" as const,
   207				startedAt,
   208			})),
   209			...(startedRun.sessionFile ? { sessionFile: startedRun.sessionFile } : {}),
   210		};
   211	}
   212	
   213	function buildFailedRepair(status: AsyncStatus, asyncDir: string, now: number, reason?: string): { status: AsyncStatus; result: object; message: string } {
   214		const runId = status.runId || path.basename(asyncDir);
   215		const pid = typeof status.pid === "number" ? status.pid : "unknown";
   216		const baseMessage = reason ?? `Async runner process ${pid} exited or disappeared before writing a result. Marked run failed by stale-run reconciliation.`;
   217		const diagnostics = readRunnerStartupDiagnostics(asyncDir);
   218		const message = diagnostics ? `${baseMessage}\n\nRunner stderr tail:\n${diagnostics}` : baseMessage;
   219		const steps = status.steps?.length ? status.steps : [{ agent: "subagent", status: "running" as const }];
   220		const repairedSteps = steps.map((step) => step.status === "running" || step.status === "pending"
   221			? {
   222				...step,
   223				status: "failed" as const,
   224				activityState: undefined,
   225				endedAt: step.endedAt ?? now,
   226				durationMs: step.startedAt !== undefined && step.durationMs === undefined ? Math.max(0, now - step.startedAt) : step.durationMs,
   227				exitCode: step.exitCode ?? 1,
   228				error: step.error ?? message,
   229			}
   230			: step);
   231		const repairedStatus: AsyncStatus = {
   232			...status,
   233			state: "failed",
   234			activityState: undefined,
   235			lastUpdate: now,
   236			endedAt: now,
   237			steps: repairedSteps,
   238		};
   239		const resultAgent = repairedSteps[status.currentStep ?? 0]?.agent ?? repairedSteps[0]?.agent ?? "subagent";
   240		return {
   241			status: repairedStatus,
   242			message,
   243			result: {
   244				id: runId,
   245				agent: resultAgent,
   246				mode: status.mode,
   247				success: false,
   248				state: "failed",
   249				summary: message,
   250				results: repairedSteps.map((step) => ({
   251					agent: step.agent,
   252					output: step.status === "complete" || step.status === "completed" ? "" : message,
   253					error: step.status === "complete" || step.status === "completed" ? undefined : step.error ?? message,
   254					success: step.status === "complete" || step.status === "completed",
   255					model: step.model,
   256					attemptedModels: step.attemptedModels,
   257					modelAttempts: step.modelAttempts,
   258					sessionFile: step.sessionFile,
   259				})),
   260				exitCode: 1,
   261				timestamp: now,
   262				durationMs: Math.max(0, now - status.startedAt),
   263				asyncDir,
   264				sessionId: status.sessionId,
   265				sessionFile: status.sessionFile,
   266			},
   267		};
   268	}
   269	
   270	function writeFailedRepair(asyncDir: string, status: AsyncStatus, resultPath: string, now: number, reason?: string): ReconcileAsyncRunResult {
   271		const repair = buildFailedRepair(status, asyncDir, now, reason);
   272		writeAtomicJson(resultPath, repair.result);
   273		writeAtomicJson(path.join(asyncDir, "status.json"), repair.status);
   274		appendJsonlBestEffort(path.join(asyncDir, "events.jsonl"), {
   275			type: "subagent.run.repaired_stale",
   276			ts: now,
   277			runId: repair.status.runId,
   278			pid: status.pid,
   279			resultPath,
   280			message: repair.message,
   281		});
   282		return { status: repair.status, repaired: true, resultPath, message: repair.message };
   283	}
   284	
   285	function terminal(state: AsyncStatus["state"]): boolean {
   286		return state === "complete" || state === "failed" || state === "paused" || state === "stopped";
   287	}
   288	
   289	function* nestedRuns(children: NestedRunSummary[] | undefined): Generator<NestedRunSummary> {
   290		for (const child of children ?? []) {
   291			yield child;
   292			yield* nestedRuns(child.children);
   293			yield* nestedRuns(child.steps?.flatMap((step) => step.children ?? []));
   294		}
   295	}
   296	
   297	export function reconcileNestedAsyncDescendants(route: NestedRoute, options: ReconcileAsyncRunOptions = {}): void {
   298		const registry = projectNestedEvents(route);
   299		for (const run of nestedRuns(registry.children)) {
   300			if (run.state !== "running" && run.state !== "queued") continue;
   301			const asyncDir = resolveNestedAsyncDir(route.rootRunId, run);
   302			if (!asyncDir) continue;
   303			const result = reconcileAsyncRun(asyncDir, {
   304				...options,
   305				resultsDir: path.join(options.resultsDir ?? RESULTS_DIR, "nested", route.rootRunId),
   306			});
   307			const status = result.status;
   308			if (!status) continue;
   309			if (!result.repaired && !terminal(status.state)) continue;
   310			const ts = options.now?.() ?? Date.now();
   311			writeNestedEvent(route, {
   312				type: terminal(status.state) ? "subagent.nested.completed" : "subagent.nested.updated",
   313				ts,
   314				parentRunId: run.parentRunId,
   315				parentStepIndex: run.parentStepIndex,
   316				child: nestedSummaryFromAsyncStatus(status, asyncDir, {
   317					id: run.id,
   318					parentRunId: run.parentRunId,
   319					parentStepIndex: run.parentStepIndex,
   320					depth: run.depth,
   321					path: run.path,
   322					mode: run.mode,
   323					ts,
   324				}),
   325			});
   326		}
   327	}
   328	
   329	export function checkPidLiveness(pid: number, kill: KillFn = process.kill): PidLiveness {
   330		try {
   331			kill(pid, 0);
   332			return "alive";
   333		} catch (error) {
   334			const code = typeof error === "object" && error !== null && "code" in error
   335				? (error as NodeJS.ErrnoException).code
   336				: undefined;
   337			if (code === "ESRCH") return "dead";
   338			if (code === "EPERM") return "unknown";
   339			return "unknown";
   340		}
   341	}
   342	
   343	export function reconcileAsyncRun(asyncDir: string, options: ReconcileAsyncRunOptions = {}): ReconcileAsyncRunResult {
   344		const now = options.now?.() ?? Date.now();
   345		const status = readStatusFile(asyncDir);
   346		const startedStatus = !status && options.startedRun ? buildStartedStatus(asyncDir, options.startedRun, now) : undefined;
   347		const effectiveStatus = status ?? startedStatus;
   348		if (!effectiveStatus) return { status: null, repaired: false };
   349		const statusPath = path.join(asyncDir, "status.json");
   350		for (const [index, step] of (effectiveStatus.steps ?? []).entries()) {
   351			const stepRecord = step as Record<string, unknown>;
   352			if (stepRecord.model !== undefined && typeof stepRecord.model !== "string") throw new Error(`Invalid async status file '${statusPath}': steps[${index}].model must be a string.`);
   353			if (stepRecord.thinking !== undefined && typeof stepRecord.thinking !== "string") throw new Error(`Invalid async status file '${statusPath}': steps[${index}].thinking must be a string.`);
   354		}
   355	
   356		const runId = effectiveStatus.runId || path.basename(asyncDir);
   357		const resultPath = path.join(options.resultsDir ?? RESULTS_DIR, `${runId}.json`);
   358		if (fs.existsSync(resultPath)) {
   359			const terminalStatus = effectiveStatus.state === "running" || effectiveStatus.state === "queued"
   360				? terminalStatusFromResult(effectiveStatus, resultPath, now)
   361				: undefined;
   362			if (terminalStatus) {
   363				writeAtomicJson(path.join(asyncDir, "status.json"), terminalStatus);
   364				return { status: terminalStatus, repaired: true, resultPath, message: "Existing async result file was used to repair stale running status." };
   365			}
   366			return { status: effectiveStatus, repaired: false, resultPath };
   367		}
   368	
   369		if (effectiveStatus.state !== "running" || typeof effectiveStatus.pid !== "number") {
   370			return { status: status ?? null, repaired: false, resultPath };
   371		}
   372	
   373		if (!status) {
   374			const startedAt = options.startedRun?.startedAt ?? effectiveStatus.startedAt;
   375			if (now - startedAt < (options.missingStatusGraceMs ?? 1000)) {
   376				return { status: null, repaired: false, resultPath };
   377			}
   378		}
   379	
   380		const liveness = checkPidLiveness(effectiveStatus.pid, options.kill);
   381		if (liveness !== "dead") {
   382			const staleAfterMs = options.staleAlivePidMs ?? 24 * 60 * 60 * 1000;
   383			const lastUpdate = effectiveStatus.lastUpdate ?? effectiveStatus.startedAt;
   384			if (now - lastUpdate <= staleAfterMs) return { status: status ?? null, repaired: false, resultPath };
   385			const message = `Async runner process ${effectiveStatus.pid} still has a live PID, but status has not updated for ${now - lastUpdate}ms. Marked run failed by stale-run reconciliation because PID ownership cannot be verified.`;
   386			return writeFailedRepair(asyncDir, effectiveStatus, resultPath, now, message);
   387		}
   388	
   389		return writeFailedRepair(asyncDir, effectiveStatus, resultPath, now);
   390	}

